              "heading": "Смысл предела",
              "body": "Запись lim(x→a) f(x) = L означает: значения f(x) становятся сколь угодно близки к L, когда x достаточно близок к a, но не обязательно равен a. Функция может вообще не быть определена в самой точке a. Предел описывает поведение вокруг точки, а не результат запрещённой подстановки.\nНапример, (x² − 1)/(x − 1) при x ≠ 1 равна x + 1. В точке 1 исходное выражение не определено, но рядом его значения приближаются к 2. Можно доопределить значение равным 2 и получить непрерывную функцию.",
