              "body": "Для однородного проводника R = ρl/S: длинный провод имеет большее сопротивление, толстый — меньшее. Удельное сопротивление ρ зависит от материала и температуры. Если ρ задано в Ом·мм²/м, длину подставляют в метрах, сечение в мм². Нельзя смешивать эту запись с Ом·м без преобразования.\nВ ограниченном температурном диапазоне для металлов используют R(T) ≈ R₀[1 + α(T − T₀)]. Это линейное приближение, а не универсальная формула для любого материала и температуры.",
