              "heading": "Почему используют действующее значение",
              "body": "Среднее значение чистой синусоиды за период равно нулю, но резистор всё равно нагревается. Действующее, или RMS, значение даёт такой же средний нагрев, как постоянный ток той же величины: I=√((1/T)∫i²dt). Для синусоиды I=Im/√2, U=Um/√2.\nЭто соотношение с √2 верно именно для синусоиды. Для прямоугольных импульсов или искажённой формы RMS находят по определению. В дальнейших комплексных расчётах U и I без индекса m — действующие значения.",
